globalThis.ragSearchTexts=globalThis.ragSearchTexts||{};globalThis.ragSearchTexts["417"]={"1862":"Календарь олимпиад 2026/27\nНЕПОЛНАЯ ЦИТАТА (https://t.me/kruzhok102_olproga/61):\nРасписание_олимпиад_по_информатике_2026_2027_Кружок102.pdf\n\nКраткое описание:\nPDF-календарь олимпиад по информатике на сезон 2026/27 от Кружка 102. Доступно название файла; сами даты в поисковый текст пока не извлечены.\nПоисковая тема: даты и расписание."};
